//! Colors: Caelestia's Material You palette (generated from the wallpaper),
//! Catppuccin Mocha without it, or the terminal's own colors (t).

use std::path::PathBuf;
use std::time::SystemTime;

use ratatui::style::{Color, Modifier, Style};

/// Material You colors generated by Caelestia from the wallpaper.
pub fn scheme_path() -> PathBuf {
    crate::cfg::home().join(".local/state/caelestia/scheme.json")
}

pub fn scheme_mtime() -> Option<SystemTime> {
    std::fs::metadata(scheme_path()).and_then(|m| m.modified()).ok()
}

#[derive(Clone, Debug)]
pub struct Theme {
    /// The terminal's own colors: no blending, dim and reverse instead.
    pub ansi: bool,
    pub dark: bool,
    pub primary: Color,
    pub accent: Color,
    pub error: Color,
    pub warning: Color,
    pub success: Color,
    pub fg: Color,
    pub bg: Color,
    pub panel: Color,
}

fn hex(s: &str) -> Option<Color> {
    let s = s.trim_start_matches('#');
    if s.len() != 6 {
        return None;
    }
    let v = u32::from_str_radix(s, 16).ok()?;
    Some(Color::Rgb((v >> 16) as u8, (v >> 8) as u8, v as u8))
}

pub fn to_hex(c: Color) -> Option<String> {
    match c {
        Color::Rgb(r, g, b) => Some(format!("#{r:02x}{g:02x}{b:02x}")),
        _ => None,
    }
}

/// Whether the Caelestia palette is dark, and its colors by name.
pub fn caelestia_scheme() -> Option<(bool, serde_json::Map<String, serde_json::Value>)> {
    let text = std::fs::read_to_string(scheme_path()).ok()?;
    let json: serde_json::Value = serde_json::from_str(&text).ok()?;
    let colours = json.get("colours")?.as_object()?.clone();
    let dark = json.get("mode").and_then(|m| m.as_str()).unwrap_or("dark") == "dark";
    Some((dark, colours))
}

impl Theme {
    /// Textual's catppuccin-mocha, nixcfg's colors without Caelestia.
    pub fn fallback() -> Self {
        let c = |s| hex(s).unwrap();
        Theme {
            ansi: false,
            dark: true,
            primary: c("#F5C2E7"),
            accent: c("#fab387"),
            error: c("#F28FAD"),
            warning: c("#FAE3B0"),
            success: c("#ABE9B3"),
            fg: c("#cdd6f4"),
            bg: c("#181825"),
            panel: c("#45475a"),
        }
    }

    pub fn caelestia() -> Option<Self> {
        let (dark, colours) = caelestia_scheme()?;
        let get = |k: &str| colours.get(k).and_then(|v| v.as_str()).and_then(hex);
        Some(Theme {
            ansi: false,
            dark,
            primary: get("primary")?,
            accent: get("tertiary")?,
            error: get("error")?,
            warning: get("term3").or(get("tertiary"))?,
            success: get("term2").or(get("secondary"))?,
            fg: get("onSurface")?,
            bg: get("background")?,
            panel: get("surfaceContainer")?,
        })
    }

    /// The terminal's 16 colors (Textual's ansi-dark / ansi-light).
    pub fn terminal(dark: bool) -> Self {
        Theme {
            ansi: true,
            dark,
            primary: Color::Blue,
            accent: Color::Magenta,
            error: Color::Red,
            warning: Color::Yellow,
            success: Color::Green,
            fg: Color::Reset,
            bg: Color::Reset,
            panel: Color::Reset,
        }
    }

    /// The current theme: Caelestia's, or the fallback; the terminal's with `terminal`.
    pub fn load(terminal: bool) -> Self {
        let caelestia = Theme::caelestia();
        if terminal {
            return Theme::terminal(caelestia.as_ref().is_none_or(|t| t.dark));
        }
        caelestia.unwrap_or_else(Theme::fallback)
    }

    /// `color pct%` in Textual's CSS: the color blended over a base.
    pub fn mix_on(&self, color: Color, pct: f32, base: Color) -> Color {
        match (color, base) {
            (Color::Rgb(r, g, b), Color::Rgb(br, bg, bb)) => {
                let m = |a: u8, b: u8| (a as f32 * pct + b as f32 * (1.0 - pct)).round() as u8;
                Color::Rgb(m(r, br), m(g, bg), m(b, bb))
            }
            _ => color,
        }
    }

    pub fn mix(&self, color: Color, pct: f32) -> Color {
        self.mix_on(color, pct, self.bg)
    }

    pub fn base(&self) -> Style {
        Style::default().fg(self.fg).bg(self.bg)
    }

    /// Rich's [dim].
    pub fn dim(&self) -> Style {
        if self.ansi {
            Style::default().add_modifier(Modifier::DIM)
        } else {
            Style::default().fg(self.mix(self.fg, 0.5))
        }
    }

    /// Textual's $text-muted.
    pub fn muted(&self) -> Style {
        if self.ansi {
            Style::default().add_modifier(Modifier::DIM)
        } else {
            Style::default().fg(self.mix(self.fg, 0.65))
        }
    }

    pub fn fg_of(&self, c: Color) -> Style {
        Style::default().fg(c)
    }

    /// A thin column border ($foreground 10%).
    pub fn rule(&self) -> Style {
        if self.ansi { self.dim() } else { Style::default().fg(self.mix(self.fg, 0.12)) }
    }

    /// The highlighted row of a list: tinted with the primary color when the
    /// list has the focus.
    pub fn highlight(&self, focused: bool) -> Style {
        match (self.ansi, focused) {
            (true, true) => Style::default().fg(self.primary).add_modifier(Modifier::BOLD | Modifier::REVERSED),
            (true, false) => Style::default().add_modifier(Modifier::BOLD),
            (false, true) => Style::default()
                .bg(self.mix(self.primary, 0.15))
                .fg(self.primary)
                .add_modifier(Modifier::BOLD),
            (false, false) => Style::default().bg(self.mix(self.fg, 0.06)),
        }
    }

    pub fn scrollbar(&self) -> (Style, Style) {
        if self.ansi {
            (Style::default(), Style::default().fg(self.primary))
        } else {
            (Style::default().fg(self.bg), Style::default().fg(self.mix(self.primary, 0.3)))
        }
    }
}

/// Escape codes giving the terminal the colors of a theme while a command
/// runs: OSC 10/11 the default foreground and background, OSC 4 the 16 ANSI
/// colors (from Caelestia's term0-15). kitty and tmux both understand them;
/// PALETTE_RESET puts the terminal's back.
pub fn terminal_palette(theme: &Theme) -> String {
    let mut codes = String::new();
    if let Some((_, c)) = caelestia_scheme() {
        for i in 0..16 {
            if let Some(v) = c.get(&format!("term{i}")).and_then(|v| v.as_str()) {
                codes += &format!("\x1b]4;{i};#{}\x1b\\", v.trim_start_matches('#'));
            }
        }
    }
    if let Some(fg) = to_hex(theme.fg) {
        codes += &format!("\x1b]10;{fg}\x1b\\");
    }
    if let Some(bg) = to_hex(theme.bg) {
        codes += &format!("\x1b]11;{bg}\x1b\\");
    }
    // Clears the screen so it is painted with the new background.
    codes + "\x1b[2J\x1b[H"
}

pub const PALETTE_RESET: &str = "\x1b]104\x1b\\\x1b]110\x1b\\\x1b]111\x1b\\";
